"""World semantic implementation over SQLite storage.

The calculus is CONSTITUTION.md. This module is the current kernel *mechanism*:
domain vocabularies live in fixture/config code; construction origin is
recorded beside the World database as sidecar metadata.
"""

from __future__ import annotations

import json
import stat
from collections.abc import Iterable, Mapping, Sequence
from pathlib import Path
from typing import Any

from ontology_author.world.core.model import (
    Completeness,
    Grounding,
    GroundingKind,
    RelationMode,
    Role,
    RoleType,
)
from ontology_author.world.core.store import WorldStore

from ontology_author.world.core.origins import ConstructionOrigin, OriginMetadataError
from ontology_author.world.core.source import AssertionGrounding, SourceObservation


def _origin_path(db_path: Path) -> Path:
    return Path(str(db_path) + ".origins.json")


class SemanticWorld:
    """One versioned semantic World backed by SQLite storage."""

    def __init__(self, path: Path | str, *, world_id: str, read_only: bool = False) -> None:
        self.path = Path(path)
        self.world_id = world_id
        self.read_only = read_only
        original_mode: int | None = None
        if read_only and self.path.exists():
            original_mode = stat.S_IMODE(self.path.stat().st_mode)
            self.path.chmod(original_mode | stat.S_IWUSR)
        try:
            self._store = WorldStore(self.path, world_id=world_id, purpose_ref="")
        finally:
            if original_mode is not None:
                self.path.chmod(original_mode)
        self._origins: dict[str, str] = {}
        sidecar = _origin_path(self.path)
        if sidecar.exists():
            payload = json.loads(sidecar.read_text(encoding="utf-8"))
            self._origins = dict(payload.get("assertions", {}))

    def close(self) -> None:
        if not self.read_only:
            self._persist_origins()
        self._store.close()

    def _persist_origins(self) -> None:
        _origin_path(self.path).write_text(
            json.dumps(
                {"world_id": self.world_id, "assertions": self._origins},
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )

    def add_referent(
        self,
        referent_id: str,
        *,
        label: str = "",
        observations: Iterable[SourceObservation] = (),
    ) -> str:
        return self._store.add_referent(
            referent_id,
            label=label,
            grounding=_observation_groundings(observations),
        )

    def declare_relation(
        self,
        name: str,
        roles: Sequence[Role],
        *,
        mode: RelationMode = RelationMode.BASE,
        description: str = "",
    ) -> str:
        return self._store.declare_relation(
            name, roles, mode=mode, description=description
        )

    def assert_tuple(
        self,
        relation: str,
        values: Mapping[str, Any],
        *,
        origin: ConstructionOrigin,
        grounding: AssertionGrounding | None = None,
    ):
        if origin is ConstructionOrigin.DERIVED:
            raise ValueError("BASE assert cannot use DERIVED origin")
        grounds = list(_assertion_groundings(grounding, origin))
        result = self._store.assert_tuple(relation, values, grounding=grounds)
        self._origins[result.assertion_id] = origin.value
        self._persist_origins()
        return result

    def retract_tuple(self, relation: str, values: Mapping[str, Any]) -> bool:
        assertion_id = self._store.assertion_id_for_tuple(relation, values)
        removed = self._store.retract_tuple(relation, values)
        if removed:
            self._origins.pop(assertion_id, None)
            self._persist_origins()
        return removed

    def register_derivation(
        self, relation: str, *, sql: str, inputs: Sequence[str]
    ) -> None:
        self._store.register_derivation(relation, sql=sql, inputs=inputs)

    def rerun(self, relation: str, *, completeness: Completeness):
        result = self._store.run_derivation(relation, completeness=completeness)
        for row in self._store.query(
            "SELECT assertion_id FROM _world_assertions WHERE relation_name = ?",
            (relation,),
        ):
            self._origins[row["assertion_id"]] = ConstructionOrigin.DERIVED.value
        self._persist_origins()
        return result

    def is_stale(self, relation: str) -> bool:
        return self._store.is_stale(relation)

    def stale_relations(self) -> list[str]:
        return self._store.stale_relations()

    def derivation_state(self, relation: str) -> str:
        return self._store.derivation_state(relation)

    def latest_completeness(self, relation: str) -> dict[str, Any] | None:
        return self._store.latest_completeness(relation)

    def query(self, sql: str, parameters: Sequence[Any] = ()) -> list[dict[str, Any]]:
        return self._store.query(sql, parameters)

    def query_semantic(
        self, sql: str, parameters: Sequence[Any] = ()
    ) -> list[dict[str, Any]]:
        return self._store.query_semantic(sql, parameters)

    def inspect_tuple(
        self, relation: str, values: Mapping[str, Any]
    ) -> dict[str, Any] | None:
        detail = self._store.inspect_tuple(relation, values)
        if detail is None:
            return None
        assertion_id = self._store.assertion_id_for_tuple(relation, values)
        detail["construction_origin"] = self.origin_for_assertion(assertion_id)
        return detail

    def origin_for_assertion(self, assertion_id: str) -> str:
        if assertion_id in self._origins:
            return self._origins[assertion_id]
        rows = self._store.query(
            "SELECT origin FROM _world_assertions WHERE assertion_id = ?",
            (assertion_id,),
        )
        if not rows:
            raise OriginMetadataError(
                f"no assertion {assertion_id!r} has a construction origin"
            )
        if rows[0]["origin"] == "DERIVED":
            return ConstructionOrigin.DERIVED.value
        raise OriginMetadataError(
            f"asserted tuple {assertion_id!r} has no construction origin"
        )

    def origin_account(self) -> dict[str, int]:
        counts = {origin.value: 0 for origin in ConstructionOrigin}
        for row in self._store.query(
            "SELECT assertion_id FROM _world_assertions"
        ):
            origin = self.origin_for_assertion(row["assertion_id"])
            counts[origin] = counts.get(origin, 0) + 1
        return counts

    def relation_tuples(self, relation: str) -> set[tuple[Any, ...]]:
        roles = self._store.relation_schema(relation)["roles"]
        columns = [role["column"] for role in roles]
        rows = self._store.query(
            f"SELECT {', '.join(columns)} FROM {relation} ORDER BY {', '.join(columns)}"
        )
        return {tuple(row[column] for column in columns) for row in rows}


def _observation_groundings(
    observations: Iterable[SourceObservation],
) -> list[Grounding]:
    grounds = []
    for observation in observations:
        pointer = observation.as_pointer()
        grounds.append(
            Grounding(
                GroundingKind.SOURCE,
                f"{observation.provider}://{observation.native_handle}@{observation.source_revision}",
                json.dumps(pointer, sort_keys=True, separators=(",", ":")),
            )
        )
    return grounds


def _assertion_groundings(
    grounding: AssertionGrounding | None,
    origin: ConstructionOrigin,
) -> list[Grounding]:
    if grounding is None:
        return [
            Grounding(
                GroundingKind.WORLD,
                f"origin:{origin.value}",
                json.dumps(
                    {"construction_origin": origin.value},
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            )
        ]
    grounds = _observation_groundings(grounding.observations)
    payload = {
        "construction_origin": origin.value,
        "construction_method": grounding.construction_method,
        "observations": [item.as_pointer() for item in grounding.observations],
    }
    if grounding.extra:
        payload["extra"] = grounding.extra
    grounds.append(
        Grounding(
            GroundingKind.WORLD,
            f"origin:{origin.value}",
            json.dumps(payload, sort_keys=True, separators=(",", ":")),
        )
    )
    return grounds

"""Fail-closed construction boundary over the World semantic implementation.

WORLD BASE requires SOURCE grounding; PURPOSE-scoped rows may omit it.
Admission scope is a sidecar mechanism for the WORLD vs PURPOSE invariant.
"""

from __future__ import annotations

import json
import sqlite3
from collections.abc import Iterable, Mapping, Sequence
from pathlib import Path
from typing import Any, Literal

from ontology_author.world.core.model import Completeness, RelationMode, Role, RoleType

from ontology_author.world.core.kernel import SemanticWorld
from ontology_author.world.core.origins import ConstructionOrigin
from ontology_author.world.core.source import AssertionGrounding, SourceObservation

Scope = Literal["WORLD", "PURPOSE"]


class GroundingError(ValueError):
    """WORLD BASE was asserted without SOURCE grounding."""


class ConstructionError(ValueError):
    """construction.py is malformed or did not produce a World."""


def world_id_of(db_path: Path | str) -> str:
    connection = sqlite3.connect(f"file:{Path(db_path)}?mode=ro", uri=True)
    try:
        row = connection.execute(
            "SELECT world_id FROM _world_meta WHERE singleton = 1"
        ).fetchone()
    finally:
        connection.close()
    if row is None:
        raise ConstructionError(f"{db_path} is not an Ontology Author World")
    return str(row[0])


def has_source_grounding(grounding: AssertionGrounding | None) -> bool:
    if grounding is None:
        return False
    for observation in grounding.observations:
        if not isinstance(observation, SourceObservation):
            continue
        if str(observation.native_handle or "").strip() and str(
            observation.source_revision or ""
        ).strip():
            return True
    return False


class ConstructionWorld:
    """SemanticWorld plus relation scope and WORLD-BASE SOURCE enforcement."""

    def __init__(self, inner: SemanticWorld) -> None:
        self._inner = inner
        self.admission: dict[str, Scope] = {}

    @classmethod
    def create(cls, path: Path | str, *, world_id: str) -> "ConstructionWorld":
        return cls(SemanticWorld(path, world_id=world_id))

    @classmethod
    def open(cls, path: Path | str, *, world_id: str | None = None) -> "ConstructionWorld":
        db_path = Path(path)
        inner = SemanticWorld(
            db_path, world_id=world_id or world_id_of(db_path), read_only=True
        )
        world = cls(inner)
        admission_path = db_path.parent / "world.admission.json"
        if admission_path.exists():
            world.load_admission(admission_path)
        return world

    @property
    def path(self) -> Path:
        return self._inner.path

    @property
    def world_id(self) -> str:
        return self._inner.world_id

    def close(self) -> None:
        self._inner.close()

    def add_referent(
        self,
        referent_id: str,
        *,
        label: str = "",
        observations: Iterable[SourceObservation] = (),
    ) -> str:
        if self._inner.read_only:
            raise ConstructionError("World is read-only")
        return self._inner.add_referent(
            referent_id, label=label, observations=observations
        )

    def declare_relation(
        self,
        name: str,
        roles: Sequence[Role],
        *,
        mode: RelationMode = RelationMode.BASE,
        description: str = "",
        scope: Scope = "WORLD",
    ) -> str:
        if self._inner.read_only:
            raise ConstructionError("World is read-only")
        if scope not in ("WORLD", "PURPOSE"):
            raise ConstructionError(f"scope must be WORLD or PURPOSE, got {scope!r}")
        declared = self._inner.declare_relation(
            name, roles, mode=mode, description=description
        )
        self.admission[declared] = scope
        return declared

    def assert_tuple(
        self,
        relation: str,
        values: Mapping[str, Any],
        *,
        origin: ConstructionOrigin,
        grounding: AssertionGrounding | None = None,
    ):
        if self._inner.read_only:
            raise ConstructionError("World is read-only")
        scope = self._scope(relation)
        mode = self._inner._store.relation_schema(relation)["mode"]
        if mode == RelationMode.DERIVED.value:
            raise ConstructionError(
                f"derived relation {relation!r} cannot be asserted; use register_derivation"
            )
        if scope == "WORLD" and not has_source_grounding(grounding):
            raise GroundingError(
                f"WORLD BASE {relation!r} requires SOURCE grounding with a non-empty reference"
            )
        return self._inner.assert_tuple(
            relation, values, origin=origin, grounding=grounding
        )

    def retract_tuple(self, relation: str, values: Mapping[str, Any]) -> bool:
        if self._inner.read_only:
            raise ConstructionError("World is read-only")
        return self._inner.retract_tuple(relation, values)

    def register_derivation(
        self, relation: str, *, sql: str, inputs: Sequence[str]
    ) -> None:
        if self._inner.read_only:
            raise ConstructionError("World is read-only")
        self._inner.register_derivation(relation, sql=sql, inputs=inputs)

    def rerun(self, relation: str, *, completeness: Completeness):
        if self._inner.read_only:
            raise ConstructionError("World is read-only")
        return self._inner.rerun(relation, completeness=completeness)

    def query_semantic(
        self, sql: str, parameters: Sequence[Any] = ()
    ) -> list[dict[str, Any]]:
        return self._inner.query_semantic(sql, parameters)

    def query(self, sql: str, parameters: Sequence[Any] = ()) -> list[dict[str, Any]]:
        return self._inner.query(sql, parameters)

    def relation_schema(self, relation: str) -> dict[str, Any]:
        return self._inner._store.relation_schema(relation)

    def relation_rows(self, relation: str) -> list[dict[str, Any]]:
        schema = self.relation_schema(relation)
        column_to_role = {role["column"]: role["name"] for role in schema["roles"]}
        physical = self.query_semantic(f'SELECT * FROM "{relation}"')
        rows = []
        for row in physical:
            rows.append(
                {column_to_role.get(key, key): value for key, value in row.items()}
            )
        return rows

    def load_admission(self, path: Path | str) -> None:
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
        relations = payload.get("relations") or {}
        self.admission = {
            str(name): ("PURPOSE" if str(scope) == "PURPOSE" else "WORLD")
            for name, scope in relations.items()
        }

    def admission_payload(self) -> dict[str, Any]:
        return {"relations": dict(sorted(self.admission.items()))}

    def _scope(self, relation: str) -> Scope:
        if relation not in self.admission:
            raise ConstructionError(
                f"relation {relation!r} has no admission scope; declare_relation first"
            )
        return self.admission[relation]


def role_text(name: str) -> Role:
    return Role(name, RoleType.TEXT)


def role_referent(name: str) -> Role:
    return Role(name, RoleType.REFERENT)

"""Project root: PURPOSE.md + construction.py → candidate → World.

``construction.py`` is the current authoring shape, not ontology. Evidence is
the ordinary project tree.
"""

from __future__ import annotations

import sys
from pathlib import Path
from typing import Any

from ontology_author.world.core.model import RelationMode, Role, RoleType

from ontology_author.world.core.origins import ConstructionOrigin
from ontology_author.world.core.source import AssertionGrounding, SourceObservation
from ontology_author.world.runtime.commit import (
    RunResult,
    discard_candidate,
    _replace_candidate,
    validate_world_base_source,
    write_sidecars,
)
from ontology_author.world.runtime.purpose import Purpose, ensure_failure_relation
from ontology_author.world.runtime.source_helpers import Source
from ontology_author.world.runtime.world import (
    ConstructionError,
    ConstructionWorld,
    GroundingError,
)

WORLD_ID = "v0"


class Project:
    def __init__(self, root: Path | str, *, project_root: Path | str | None = None) -> None:
        self.root = Path(root)
        self.project_root = (
            Path(project_root)
            if project_root is not None
            else self._infer_project_root(self.root)
        )
        self.candidate_dir = self.root / "candidate"
        self.world_dir = self.root / "world"

    @staticmethod
    def _infer_project_root(root: Path) -> Path:
        resolved = root.resolve()
        return resolved.parent.parent if resolved.parent.name == ".worlds" else resolved

    @property
    def world_path(self) -> Path:
        return self.world_dir / "world.sqlite"

    def run(self, construction: Path | str | None = None) -> RunResult:
        construction_path = Path(construction) if construction else self.root / "construction.py"
        purpose_text = ""
        purpose_file = self.root / "PURPOSE.md"
        if purpose_file.exists():
            purpose_text = purpose_file.read_text(encoding="utf-8")

        discard_candidate(self.candidate_dir)
        self.candidate_dir.mkdir(parents=True)
        db_path = self.candidate_dir / "world.sqlite"
        world = ConstructionWorld.create(db_path, world_id=WORLD_ID)
        purpose: Purpose | None = None
        try:
            ensure_failure_relation(world)
            purpose = Purpose(world, text=purpose_text)
            source = Source(self.project_root)
            namespace = _construction_namespace(source, world, purpose)
            if not construction_path.exists():
                raise ConstructionError("construction.py missing")
            code = construction_path.read_text(encoding="utf-8")
            import_roots = [str(self.root.resolve()), str(self.project_root.resolve())]
            inserted = [path for path in import_roots if path not in sys.path]
            for path in reversed(inserted):
                sys.path.insert(0, path)
            try:
                exec(compile(code, str(construction_path), "exec"), namespace, namespace)
                construct = namespace.get("construct")
                if not callable(construct):
                    raise ConstructionError("construction.py must define construct(source, world, purpose)")
                construct(source, world, purpose)
            finally:
                for path in inserted:
                    try:
                        sys.path.remove(path)
                    except ValueError:
                        pass
            write_sidecars(world, purpose.payload())
            report = validate_world_base_source(world)
            world.close()
            world = None  # type: ignore[assignment]
            if not report.ok:
                discard_candidate(self.candidate_dir)
                return RunResult(
                    succeeded=False,
                    reason=report.reason,
                    errors=tuple(
                        f"{item['relation']}:{item['assertion_id']}" for item in report.ungrounded
                    ),
                )
            _replace_candidate(self.candidate_dir, self.world_dir)
            return RunResult(succeeded=True, world_dir=self.world_dir)
        except (GroundingError, ConstructionError, Exception) as exc:
            if world is not None:
                try:
                    world.close()
                except Exception:
                    pass
            discard_candidate(self.candidate_dir)
            if isinstance(exc, GroundingError):
                return RunResult(succeeded=False, reason="ungrounded_world_base", errors=(str(exc),))
            if isinstance(exc, ConstructionError):
                return RunResult(succeeded=False, reason="construction_error", errors=(str(exc),))
            return RunResult(
                succeeded=False,
                reason="construction_error",
                errors=(f"{type(exc).__name__}: {exc}",),
            )

    def open_world(self) -> ConstructionWorld:
        if not self.world_path.exists():
            raise ConstructionError("no World has been built")
        return ConstructionWorld.open(self.world_path, world_id=WORLD_ID)


def _construction_namespace(source: Source, world: ConstructionWorld, purpose: Purpose) -> dict[str, Any]:
    return {
        "Source": Source,
        "source": source,
        "world": world,
        "purpose": purpose,
        "Role": Role,
        "RoleType": RoleType,
        "RelationMode": RelationMode,
        "ConstructionOrigin": ConstructionOrigin,
        "AssertionGrounding": AssertionGrounding,
        "SourceObservation": SourceObservation,
        "GroundingError": GroundingError,
        "ConstructionError": ConstructionError,
    }


__all__ = ["Project", "WORLD_ID"]

"""Reconstructible source helpers. Not World semantics. No persistent Source IR."""

from __future__ import annotations

import csv
import hashlib
import json
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any

from ontology_author.world.core.source import AssertionGrounding, SourceObservation

_STRUCTURED = {".csv", ".json"}


def looks_numeric(value: Any) -> bool:
    text = str(value or "").strip().replace(",", "")
    if not text:
        return False
    try:
        float(text)
        return True
    except ValueError:
        return False


class Source:
    def __init__(self, root: str | Path = ".") -> None:
        self.root = Path(root)

    def _path(self, name: str) -> Path:
        """Resolve an evidence path relative to the ordinary project tree."""

        return self.root / name

    def tables(self) -> list[str]:
        if not self.root.exists():
            return []
        names: set[str] = set()
        for directory in [self.root]:
            names.update(
                path.name
                for path in directory.iterdir()
                if path.is_file() and path.suffix.lower() in _STRUCTURED
            )
        return sorted(names)

    def _load(self, table: str) -> list[dict[str, Any]]:
        path = self._path(table)
        if not path.exists():
            raise FileNotFoundError(table)
        if path.suffix.lower() == ".json":
            payload = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(payload, list):
                return [row if isinstance(row, dict) else {"value": row} for row in payload]
            if isinstance(payload, dict):
                return [payload]
            return []
        with path.open(encoding="utf-8", newline="") as handle:
            return list(csv.DictReader(handle))

    def rows(self, table: str) -> list[dict[str, Any]]:
        return self._load(table)

    def fields(self, table: str) -> list[str]:
        rows = self._load(table)
        if not rows:
            return []
        return list(rows[0].keys())

    def profile(self, table: str, field: str) -> dict[str, Any]:
        rows = self._load(table)
        values = ["" if row.get(field) is None else str(row.get(field)) for row in rows]
        nonempty = [value for value in values if value.strip()]
        return {
            "table": table,
            "field": field,
            "n": len(values),
            "n_empty": len(values) - len(nonempty),
            "n_distinct": len(set(nonempty)),
            "n_numeric": sum(1 for value in nonempty if looks_numeric(value)),
            "sample_distinct": sorted(set(nonempty), key=lambda item: (len(item), item))[:25],
        }

    def distinct_values(self, table: str, field: str, limit: int = 50) -> list[dict[str, Any]]:
        counts: Counter[str] = Counter()
        for row in self._load(table):
            counts[str(row.get(field) or "")] += 1
        return [{"value": value, "n": n} for value, n in counts.most_common(limit)]

    def join(self, left: str, right: str, on: list[tuple[str, str]]) -> list[dict[str, Any]]:
        index: dict[tuple, list[dict[str, Any]]] = defaultdict(list)
        for row in self._load(right):
            key = tuple(str(row.get(right_field) or "") for _, right_field in on)
            index[key].append(row)
        out: list[dict[str, Any]] = []
        for left_row in self._load(left):
            key = tuple(str(left_row.get(left_field) or "") for left_field, _ in on)
            for right_row in index.get(key, []):
                merged = {f"l.{key_}": value for key_, value in left_row.items()}
                merged.update({f"r.{key_}": value for key_, value in right_row.items()})
                out.append(merged)
        return out

    def read_text(self, name: str) -> str:
        return self._path(name).read_text(encoding="utf-8")

    def file_hash(self, name: str) -> str:
        return hashlib.sha256(self._path(name).read_bytes()).hexdigest()

    def observation(self, table: str, location: str) -> SourceObservation:
        return SourceObservation(
            provider="file",
            native_handle=table,
            source_revision=self.file_hash(table),
            native_location=location,
        )

    def grounding(
        self,
        table: str,
        location: str,
        *,
        method: str = "",
        extra: dict[str, Any] | None = None,
    ) -> AssertionGrounding:
        return AssertionGrounding(
            observations=(self.observation(table, location),),
            construction_method=method,
            extra=extra,
        )

"""Deterministic purpose requirements. Failures are an ordinary PURPOSE relation.

``purpose_requirement_failure`` is a mechanism for explicit unresolvedness, not
a kernel primitive. See CONSTITUTION.md.
"""

from __future__ import annotations

import json
from collections import defaultdict
from typing import Any

from ontology_author.world.core.model import RelationMode, Role, RoleType

from ontology_author.world.core.origins import ConstructionOrigin
from ontology_author.world.runtime.source_helpers import looks_numeric
from ontology_author.world.runtime.world import ConstructionWorld

FAILURE_RELATION = "purpose_requirement_failure"

FAILURE_ROLES = (
    Role("requirement_id", RoleType.TEXT),
    Role("affected_identity", RoleType.TEXT),
    Role("failure_kind", RoleType.TEXT),
    Role("relation_name", RoleType.TEXT),
    Role("subject_json", RoleType.TEXT),
    Role("grounding_ref", RoleType.TEXT),
)


def ensure_failure_relation(world: ConstructionWorld) -> str:
    return world.declare_relation(
        FAILURE_RELATION,
        list(FAILURE_ROLES),
        mode=RelationMode.BASE,
