    record = self._relation_record(relation)
    return {
        "name": record["name"],
        "description": record["description"],
        "mode": record["mode"],
        "roles": [
            {
                "name": row["role_name"],
                "type": row["role_type"],
                "column": row["column_name"],
            }
            for row in self._roles(relation)
        ],
    }

